/bin/bash -lc "cd [workspace path] && python -c \"
import numpy as np
d = np.load('source_pixels.npz')['rgb'].astype(int)
def change_bbox(a,b,thr):
    diff = np.abs(a-b).sum(axis=2)
    ys,xs = np.where(diff>thr)
    if len(ys)==0: return None, 0
    return (int(xs.min()),int(xs.max()),int(ys.min()),int(ys.max())), len(ys)
for i in [35,36,53,54,71,72,89,90]:
    for thr in (20,40):
        bb,n = change_bbox(d[i],d[i+1],thr)
        print(i,'->',i+1,'thr',thr, bb, n)
